import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        int max = n + m;
        long[] fact = new long[max + 1];
        long[] invFact = new long[max + 1];
        fact[0] = 1;
        for (int i = 1; i <= max; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[max] = modInv(fact[max]);
        for (int i = max; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long phaseSize = 1;
        long p = 1;
        for (int i = 0; p != 0; i++) {
            p = p * (n - i) % MOD * smallInv(n + m - i, fact, invFact) % MOD;
            phaseSize = add(phaseSize, p);
        }

        long answer = 0;
        for (int k = 1; k <= n; k++) {
            long sign = ((k + 1) & 1) == 0 ? 1 : MOD - 1;
            long numPhases = (m + k) % MOD * smallInv(k, fact, invFact) % MOD;
            long ncr = fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
            long term = sign * ncr % MOD * numPhases % MOD * phaseSize % MOD;
            answer = add(answer, term);
        }
        System.out.println(answer);
    }

    static long smallInv(int x, long[] fact, long[] invFact) {
        return invFact[x] * fact[x - 1] % MOD;
    }

    static long add(long a, long b) {
        long v = a + b;
        return v < MOD ? v : v - MOD;
    }

    static long modInv(long a) {
        long g = MOD, x = 0, y = 1;
        for (long r = a; r != 0; ) {
            long q = g / r;
            g %= r;
            long t = g;
            g = r;
            r = t;
            x -= q * y;
            t = x;
            x = y;
            y = t;
        }
        x %= MOD;
        if (x < 0) x += MOD;
        return x;
    }
}
